      backup_text =
        "# Harvest Ledger #\n\n\
         # Track your harvest under the stars. Consecutive harvests of the \
         same #\n\
         # quality tier build a streak bonus. #\n\n\
         # Quality tiers from the moonlit fields, in ascending value #\n\
         type Quality =\n\
         + Bronze\n\
         + Silver\n\
         + Gold\n\
         + Starlight\n\
         in\n\n\
         # Crops that grow under the night sky #\n\
         type Crop =\n\
         + Moonmelon\n\
         + Starfruit\n\
         + Nightshade\n\
         + Glowpumpkin\n\
         + Duskwheat\n\
         in\n\n\
         # A single harvest from the garden #\n\
         type Harvest = (\n\
         crop = Crop,\n\
         quality = Quality,\n\
         quantity = Int\n\
         ) in\n\n\
         # The harvest ledger tracks all harvests and bonuses #\n\
         type Model = (\n\
         harvests = [Harvest],\n\
         totalValue = Int,\n\
         streakBonus = Int,\n\
         lastQuality = Quality\n\
         ) in\n\n\
         # Actions the farmer can take: log a harvest, or bank the streak \
         bonus #\n\
         type Action =\n\
         + RecordHarvest(Harvest)\n\
         + ClaimBonus\n\
         in\n\n\
         let cropValue(c: Crop): Int =\n\
         case c\n\
         | Moonmelon => 15\n\
         | Starfruit => 20\n\
         | Nightshade => 20\n\
         | Glowpumpkin => 12\n\
         | Duskwheat => 10\n\
         end\n\
         in\n\n\
         let qualityMultiplier(q: Quality): Int =\n\
         case q\n\
         | Bronze => 1\n\
         | Silver => 2\n\
         | Gold => 3\n\
         | Starlight => 5\n\
         end\n\
         in\n\n\
         let harvestValue(h: Harvest): Int =\n\
         cropValue(h.crop) * qualityMultiplier(h.quality) * h.quantity\n\
         in\n\n\
         let init: Model = (\n\
         harvests = [],\n\
         totalValue = 0,\n\
         streakBonus = 0,\n\
         lastQuality = Bronze\n\
         ) in\n\n\
         # A streak continues when consecutive harvests share a quality tier #\n\
         let processHarvest(ledger: Model, h: Harvest): Model =\n\
         let value = harvestValue(h) in\n\
         let isFirst = length(ledger.harvests) == 0 in\n\
         let continues = !isFirst && h.quality == ledger.lastQuality in\n\
         let newStreak = if continues then ledger.streakBonus + 5 else 0 in\n\
         (\n\
         harvests = h :: ledger.harvests,\n\
         totalValue = ledger.totalValue + value + newStreak,\n\
         streakBonus = newStreak,\n\
         lastQuality = h.quality\n\
         )\n\
         in\n\n\
         let claimBonus(ledger: Model): Model =\n\
         (\n\
         harvests = ledger.harvests,\n\
         totalValue = ledger.totalValue + ledger.streakBonus,\n\
         streakBonus = 0,\n\
         lastQuality = ledger.lastQuality\n\
         )\n\
         in\n\n\
         let update(model: Model, action: Action): Model =\n\
         case action\n\
         | RecordHarvest(h) => processHarvest(model, h)\n\
         | ClaimBonus => claimBonus(model)\n\
         end\n\
         in\n\n\
         # ===== VIEW HELPERS ===== #\n\n\
         let cropName(c: Crop): String =\n\
         case c\n\
         | Moonmelon => \"Moonmelon\"\n\
         | Starfruit => \"Starfruit\"\n\
         | Nightshade => \"Nightshade\"\n\
         | Glowpumpkin => \"Glowpumpkin\"\n\
         | Duskwheat => \"Duskwheat\"\n\
         end\n\
         in\n\n\
         let qualityLabel(q: Quality): String =\n\
         case q\n\
         | Bronze => \"Bronze\"\n\
         | Silver => \"Silver\"\n\
         | Gold => \"Gold\"\n\
         | Starlight => \"Starlight\"\n\
         end\n\
         in\n\n\
         let qualityEmoji(q: Quality): String =\n\
         case q\n\
         | Bronze => \"\240\159\165\137\"\n\
         | Silver => \"\240\159\165\136\"\n\
         | Gold => \"\240\159\165\135\"\n\
         | Starlight => \"\226\173\144\"\n\
         end\n\
         in\n\n\
         # Tier colors, in the same oklch space as the editor's own palette #\n\
         let qualityColor(q: Quality): String =\n\
         case q\n\
         | Bronze => \"oklch(58% 0.09 60)\"\n\
         | Silver => \"oklch(60% 0.02 250)\"\n\
         | Gold => \"oklch(64% 0.14 90)\"\n\
         | Starlight => \"var(--TYP)\"\n\
         end\n\
         in\n\n\
         # ===== VIEW ===== #\n\n\
         # One typeface (--code-font, inherited from the root) and a four-step \
         size #\n\
         # scale: 0.75em labels, 0.85em body, 1.2em title, 1.5em display \
         numbers. #\n\
         # Sections carry their own side padding so the rules between them run \
         the #\n\
         # full width of the card, as Hazel's own panels do. #\n\
         let sidePad: String = \"0.7em 1em\" in\n\n\
         # Outer table columns pad to 1em so the rules align with the sections #\n\
         let cellFirst: String = \"0.35em 0.5em 0.35em 1em\" in\n\
         let cell: String = \"0.35em 0.5em\" in\n\
         let cellLast: String = \"0.35em 1em 0.35em 0.5em\" in\n\n\
         # Uniform width in a two-column grid; the grid stretches each button #\n\
         let harvestButton(h: Harvest): HTML =\n\
         Button(\n\
         [OnClick(RecordHarvest(h)),\n\
         Style([(\"padding\", \"0.35em 0.6em\"), (\"background\", \
         \"var(--T1)\"),\n\
         (\"color\", qualityColor(h.quality)), (\"border\", \"1px solid \
         var(--BR1)\"),\n\
         (\"border-radius\", \"3px\"), (\"cursor\", \"pointer\"),\n\
         (\"font-family\", \"inherit\"), (\"font-size\", \"0.85em\"),\n\
         (\"text-align\", \"left\"), (\"white-space\", \"nowrap\")])],\n\
         [Text(qualityEmoji(h.quality) ++ \" \" ++ cropName(h.crop) ++ \" x\" \
         ++ string_of_int(h.quantity))]\n\
         )\n\
         in\n\n\
         let headerCell(label: String, pad: String, align: String): HTML =\n\
         Th([Style([(\"padding\", pad), (\"text-align\", align), (\"color\", \
         \"var(--BR3)\"),\n\
         (\"font-size\", \"0.75em\"), (\"font-weight\", \"bold\"),\n\
         (\"text-transform\", \"uppercase\")])],\n\
         [Text(label)])\n\
         in\n\n\
         let statBlock(label: String, color: String, value: String): HTML =\n\
         Div(\n\
         [Style([(\"text-align\", \"center\")])],\n\
         [\n\
         Div([Style([(\"font-size\", \"0.75em\"), (\"color\", \"var(--BR3)\"),\n\
         (\"text-transform\", \"uppercase\")])],\n\
         [Text(label)]),\n\
         Div([Style([(\"font-size\", \"1.5em\"), (\"color\", color), \
         (\"font-weight\", \"bold\")])],\n\
         [Text(value)])\n\
         ]\n\
         )\n\
         in\n\n\
         # Only the rows depend on the model, so only they stay inside view #\n\
         let view(model: Model): HTML =\n\
         let harvestRows: [HTML] =\n\
         let ordered: [Harvest] = reverse(model.harvests) in\n\
         mapi(ordered, fun (i, h) ->\n\
         Tr(\n\
         [Style([(\"border-top\", \"1px solid var(--BR1)\")])],\n\
         [\n\
         Td(\n\
         [Style([(\"padding\", cellFirst), (\"color\", \"var(--BR3)\")])],\n\
         [Text(string_of_int(i + 1))]\n\
         ),\n\
         Td(\n\
         [Style([(\"padding\", cell)])],\n\
         [Text(cropName(h.crop))]\n\
         ),\n\
         Td(\n\
         [Style([(\"padding\", cell), (\"color\", qualityColor(h.quality)),\n\
         (\"white-space\", \"nowrap\")])],\n\
         [Text(qualityEmoji(h.quality) ++ \" \" ++ qualityLabel(h.quality))]\n\
         ),\n\
         Td(\n\
         [Style([(\"padding\", cell), (\"text-align\", \"right\")])],\n\
         [Text(string_of_int(h.quantity))]\n\
         ),\n\
         Td(\n\
         [Style([(\"padding\", cellLast), (\"color\", \"var(--BR4)\"),\n\
         (\"text-align\", \"right\"), (\"font-weight\", \"bold\")])],\n\
         [Text(string_of_int(harvestValue(h)))]\n\
         )\n\
         ]\n\
         )\n\
         )\n\
         in\n\
         Div(\n\
         [Style([\n\
         # MVU-render is height:100%, so a vertical margin here would overflow #\n\
         # the projector box and leave a permanent scrollbar. Use padding. #\n\
         (\"max-width\", \"600px\"), (\"margin\", \"0 auto\"),\n\
         (\"font-family\", \"var(--code-font)\"), (\"font-size\", \"0.85em\"),\n\
         (\"background\", \"var(--SAND)\"), (\"color\", \"var(--STONE)\"),\n\
         (\"border\", \"1px solid var(--BR1)\"), (\"border-radius\", \"0.4em\"),\n\
         (\"overflow\", \"hidden\")\n\
         ])],\n\
         [\n\
         Div(\n\
         [Style([(\"padding\", \"0.9em 1em 0.8em\"), (\"text-align\", \
         \"center\")])],\n\
         [\n\
         Div([Style([(\"font-size\", \"1.2em\"), (\"font-weight\", \"bold\"), \
         (\"color\", \"var(--BR4)\")])],\n\
         [Text(\"\240\159\140\153 Harvest Ledger\")]),\n\
         Div([Style([(\"font-size\", \"0.75em\"), (\"color\", \"var(--BR3)\"), \
         (\"margin-top\", \"0.3em\")])],\n\
         [Text(\"Track your night garden harvests\")])\n\
         ]\n\
         ),\n\n\
         # Summary stats, banded full width against the rounded outer frame #\n\
         Div(\n\
         [Style([(\"display\", \"flex\"), (\"justify-content\", \
         \"space-around\"),\n\
         (\"padding\", sidePad), (\"background\", \"var(--T2)\"),\n\
         (\"border-top\", \"1px solid var(--BR1)\"),\n\
         (\"border-bottom\", \"1px solid var(--BR1)\")])],\n\
         [\n\
         statBlock(\"Total Value\", \"var(--BR4)\", \
         string_of_int(model.totalValue)),\n\
         statBlock(\"Streak Bonus\",\n\
         if model.streakBonus > 0 then \"var(--G0)\" else \"var(--BR3)\",\n\
         \"+\" ++ string_of_int(model.streakBonus)),\n\
         statBlock(\"Last Quality\", qualityColor(model.lastQuality), \
         qualityEmoji(model.lastQuality))\n\
         ]\n\
         ),\n\n\
         Table(\n\
         [Style([(\"width\", \"100%\"), (\"border-collapse\", \"collapse\")])],\n\
         [\n\
         Thead(\n\
         [],\n\
         [\n\
         Tr(\n\
         [],\n\
         [\n\
         headerCell(\"#\", cellFirst, \"left\"),\n\
         headerCell(\"Crop\", cell, \"left\"),\n\
         headerCell(\"Quality\", cell, \"left\"),\n\
         headerCell(\"Qty\", cell, \"right\"),\n\
         headerCell(\"Value\", cellLast, \"right\")\n\
         ]\n\
         )\n\
         ]\n\
         ),\n\
         Tbody(\n\
         [],\n\
         if length(model.harvests) == 0\n\
         then [\n\
         Tr([Style([(\"border-top\", \"1px solid var(--BR1)\")])], [\n\
         Td(\n\
         [ColSpan(5),\n\
         Style([(\"padding\", \"1.2em 1em\"), (\"text-align\", \"center\"),\n\
         (\"color\", \"var(--BR3)\")])],\n\
         [Text(\"No harvests yet... the garden awaits\")]\n\
         )\n\
         ])\n\
         ]\n\
         else harvestRows\n\
         )\n\
         ]\n\
         ),\n\n\
         Div(\n\
         [Style([(\"padding\", sidePad), (\"border-top\", \"1px solid \
         var(--BR1)\")])],\n\
         [\n\
         Div([Style([(\"font-size\", \"0.75em\"), (\"color\", \"var(--BR3)\"),\n\
         (\"text-transform\", \"uppercase\"), (\"margin-bottom\", \"0.5em\")])],\n\
         [Text(\"Record Harvest\")]),\n\
         Div(\n\
         [Style([(\"display\", \"grid\"), (\"grid-template-columns\", \"1fr \
         1fr\"),\n\
         (\"gap\", \"0.4em\")])],\n\
         [\n\
         harvestButton((crop = Moonmelon, quality = Bronze, quantity = 2)),\n\
         harvestButton((crop = Starfruit, quality = Silver, quantity = 1)),\n\
         harvestButton((crop = Nightshade, quality = Gold, quantity = 1)),\n\
         harvestButton((crop = Glowpumpkin, quality = Gold, quantity = 3)),\n\
         harvestButton((crop = Duskwheat, quality = Bronze, quantity = 4)),\n\
         harvestButton((crop = Moonmelon, quality = Starlight, quantity = 1))\n\
         ]\n\
         ),\n\
         Button(\n\
         [OnClick(ClaimBonus),\n\
         Style([(\"width\", \"100%\"), (\"margin-top\", \"0.5em\"), \
         (\"padding\", \"0.4em\"),\n\
         (\"background\", \"var(--G0)\"), (\"color\", \"var(--SAND)\"),\n\
         (\"border\", \"1px solid var(--G0)\"), (\"border-radius\", \"3px\"),\n\
         (\"cursor\", \"pointer\"), (\"font-family\", \"inherit\"),\n\
         (\"font-size\", \"0.85em\")])],\n\
         [Text(\"\240\159\146\176 Claim Bonus\")]\n\
         )\n\
         ]\n\
         ),\n\n\
         Div(\n\
         [Style([(\"padding\", \"0.6em 1em\"), (\"text-align\", \"center\"),\n\
         (\"font-size\", \"0.75em\"), (\"color\", \"var(--BR3)\"),\n\
         (\"border-top\", \"1px solid var(--BR1)\")])],\n\
         [Text(\"\240\159\140\177 \" ++ string_of_int(length(model.harvests)) \
         ++ \" harvests logged\")]\n\
         )\n\
         ]\n\
         )\n\
         in\n\n\
         let subs(_model: Model): Sub = SubNone in\n\n\
         # ===== TESTS ===== #\n\n\
         # With (model, action) order, `update` already has fold_left's shape #\n\
         let run(ledger: Model, actions: [Action]): Model =\n\
         fold_left(actions, update, ledger)\n\
         in\n\n\
         hint \"recording a harvest banks crop value x quality x quantity\"\n\
         test\n\
         let h: Harvest = (crop = Moonmelon, quality = Bronze, quantity = 2) in\n\
         let ledger = update(init, RecordHarvest(h)) in\n\
         # Moonmelon(15) * Bronze(1) * 2 = 30, no streak bonus on the first #\n\
         ledger.totalValue == 30 && length(ledger.harvests) == 1\n\
         end;\n\n\
         hint \"crop and quality set the base take\"\n\
         test\n\
         qualityMultiplier(Bronze) == 1\n\
         && qualityMultiplier(Starlight) == 5\n\
         && cropValue(Starfruit) == cropValue(Nightshade)\n\
         && harvestValue((crop = Nightshade, quality = Starlight, quantity = \
         1)) == 100\n\
         end;\n\n\
         hint \"consecutive harvests of one quality build a streak\"\n\
         test\n\
         let h1: Harvest = (crop = Moonmelon, quality = Silver, quantity = 1) in\n\
         let h2: Harvest = (crop = Starfruit, quality = Silver, quantity = 1) in\n\
         let h3: Harvest = (crop = Nightshade, quality = Silver, quantity = 1) \
         in\n\
         let ledger = run(init, [RecordHarvest(h1), RecordHarvest(h2), \
         RecordHarvest(h3)]) in\n\
         ledger.streakBonus == 10 && ledger.lastQuality == Silver\n\
         end;\n\n\
         hint \"changing quality resets the streak\"\n\
         test\n\
         let h1: Harvest = (crop = Moonmelon, quality = Bronze, quantity = 1) in\n\
         let h2: Harvest = (crop = Starfruit, quality = Gold, quantity = 1) in\n\
         let ledger = run(init, [RecordHarvest(h1), RecordHarvest(h2)]) in\n\
         ledger.streakBonus == 0\n\
         end;\n\n\
         hint \"claiming banks the bonus and clears it\"\n\
         test\n\
         let h1: Harvest = (crop = Moonmelon, quality = Gold, quantity = 1) in\n\
         let h2: Harvest = (crop = Starfruit, quality = Gold, quantity = 1) in\n\
         let earned = run(init, [RecordHarvest(h1), RecordHarvest(h2)]) in\n\
         let ledger = run(earned, [ClaimBonus]) in\n\
         ledger.streakBonus == 0\n\
         && ledger.totalValue == earned.totalValue + 5\n\
         end;\n\n\
         # Nothing here issues a command, so `update` returns a bare Model and \
         is #\n\
         # lifted into the (Model, Cmd) shape the app tuple expects. #\n\n\
         let noCmd(f: (Model, Action) -> Model): (Model, Action) -> (Model, \
         Cmd) =\n\
         fun (model, action) -> (f(model, action), CmdNone)\n\
         in\n\n\
         ^^html_sidebar((init, noCmd(update), view, subs))\n";
      refractors = "()";
    } )
